# Todd-Coxeter (HLT) over Bian-Selinger's presentation of U_N(Z[1/2,i])
# on two-level generators i[j], X[j,k], K[j,k] (j<k), to measure the
# index of subgroups generated by candidate det-1 letter alphabets.
import sys
from itertools import combinations, permutations

N = int(sys.argv[1]) if len(sys.argv) > 1 else 8

# ---- generators: name -> id; formal inverse of g is ~g
gens = {}
def gid(name):
    if name not in gens: gens[name] = len(gens)
    return gens[name]
def I(j): return gid(('i', j))
def Xg(j, k): assert j < k; return gid(('X', j, k))
def Kg(j, k): assert j < k; return gid(('K', j, k))
for j in range(N): I(j)
for j, k in combinations(range(N), 2): Xg(j, k); Kg(j, k)
NG = len(gens)
def winv(w): return [~g for g in reversed(w)]

# ---- relators (l = r stored as l . r^-1)
rels = []
def rel(l, r=[]): rels.append(l + winv(r))
for j in range(N):
    rel([I(j)] * 4)
for j, k in combinations(range(N), 2):
    rel([Xg(j, k)] * 2)
    rel([Kg(j, k)] * 8)
for j in range(N):
    for k, l in combinations(range(N), 2):
        if j != k and j != l:
            rel([I(j), Xg(k, l)], [Xg(k, l), I(j)])
            rel([I(j), Kg(k, l)], [Kg(k, l), I(j)])
for j, k in combinations(range(N), 2):
    rel([I(j), I(k)], [I(k), I(j)])
pairs = list(combinations(range(N), 2))
for (j, k), (l, m) in combinations(pairs, 2):
    if len({j, k, l, m}) == 4:
        rel([Xg(j, k), Xg(l, m)], [Xg(l, m), Xg(j, k)])
        rel([Kg(j, k), Kg(l, m)], [Kg(l, m), Kg(j, k)])
        rel([Xg(j, k), Kg(l, m)], [Kg(l, m), Xg(j, k)])
        rel([Xg(l, m), Kg(j, k)], [Kg(j, k), Xg(l, m)])
for j, k in pairs:
    rel([I(k), Xg(j, k)], [Xg(j, k), I(j)])
for j in range(N):
    for k in range(j + 1, N):
        for l in range(k + 1, N):
            rel([Xg(k, l), Xg(j, k)], [Xg(j, k), Xg(j, l)])
            rel([Xg(j, l), Xg(k, l)], [Xg(k, l), Xg(j, k)])
            rel([Kg(k, l), Xg(j, k)], [Xg(j, k), Kg(j, l)])
            rel([Kg(j, l), Xg(k, l)], [Xg(k, l), Kg(j, k)])
for j, k in pairs:
    rel([Kg(j, k), I(k), I(k)], [Xg(j, k), Kg(j, k)])
    rel([Kg(j, k)] + [I(k)] * 3, [I(k), Kg(j, k), I(k), Kg(j, k)])
    rel([Kg(j, k), I(j), I(k)], [I(j), I(k), Kg(j, k)])
    rel([Kg(j, k), Kg(j, k), I(j), I(k)])
for j, k, l, m in permutations(range(N), 4):
    if j < k and l < m and j < l and k < m and k != l:
        rel([Kg(j, k), Kg(l, m), Kg(j, l), Kg(k, m)],
            [Kg(j, l), Kg(k, m), Kg(j, k), Kg(l, m)])

# ---- candidate subgroup alphabets
def letters(which):
    L = []
    if 'mm' in which:    # -1-1 : i_a^2 i_b^2
        for a, b in combinations(range(N), 2): L.append([I(a)] * 2 + [I(b)] * 2)
    if 'mX' in which:    # -1X : i_a^2 X_bc  (any a)
        for a in range(N):
            for b, c in pairs:
                L.append([I(a)] * 2 + [Xg(b, c)])
    if 'XX' in which:    # X_ab X_cd, disjoint
        for (a, b), (c, d) in combinations(pairs, 2):
            if len({a, b, c, d}) == 4: L.append([Xg(a, b), Xg(c, d)])
    if 'KKb' in which:   # K_ab K_cd^-1 = K_ab K_cd i_c i_d, disjoint
        for (a, b) in pairs:
            for (c, d) in pairs:
                if len({a, b, c, d}) == 4:
                    L.append([Kg(a, b), Kg(c, d), I(c), I(d)])
    if 'iib' in which:   # i_a i_b^-1
        for a in range(N):
            for b in range(N):
                if a != b: L.append([I(a), ~I(b)])
    if 'i4' in which:    # i_a i_b i_c i_d, distinct
        for a, b, c, d in combinations(range(N), 4):
            L.append([I(a), I(b), I(c), I(d)])
    if 'KKmm' in which:  # K_ab K_cd i_e^2, disjoint pairs, any e
        for (a, b) in pairs:
            for (c, d) in pairs:
                if len({a, b, c, d}) == 4:
                    for e in range(N): L.append([Kg(a, b), Kg(c, d), I(e), I(e)])
    for w in which:          # gates:n -> E(gate) words at width n (N = 2^n)
        if w.startswith('gates'):
            n = N.bit_length() - 1
            assert 2 ** n == N
            L.append([I(x) for x in range(N)])                    # E(iI)
            for t in range(n):
                L.append([I(x) for x in range(N) if (x >> t) & 1])  # E(S_t)
                L.append([Kg(y, y | (1 << t)) for y in range(N)
                          if not (y >> t) & 1])                     # E(K_t)
            for v in range(n):
                for t in range(v + 1, n):
                    L.append([I(x) for x in range(N)
                              if (x >> v) & 1 and (x >> t) & 1])    # E(CS_vt)
            if 'gates+' in which:
                # scaffolding: encodings of circuits on <= 3 wires,
                # licensed by U_4 at width 2 and det +-1 at width 3
                import itertools as _it
                def xw(pred, t):
                    return [Xg(x, x | (1 << t)) for x in range(N)
                            if not (x >> t) & 1 and pred(x)]
                def zw(pred):
                    return [I(x) for x in range(N) if pred(x)] * 2
                def izw(pred, t):
                    o = []
                    for x in range(N):
                        if not (x >> t) & 1 and pred(x):
                            o += [I(x)] + [I(x | (1 << t))] * 3
                    return o
                bit = lambda v: (lambda x: (x >> v) & 1)
                for t in range(n):
                    L.append(xw(lambda x: True, t))               # X_t
                    L.append(izw(lambda x: True, t))              # iZ_t
                bitv = lambda v, e: (lambda x: ((x >> v) & 1) == e)
                for v, t in _it.permutations(range(n), 2):
                    for e in (0, 1):
                        L.append(xw(bitv(v, e), t))               # CX, either colour
                        L.append(izw(bitv(v, e), t))              # C(iZ)
                for v, t in _it.combinations(range(n), 2):
                    L.append(zw(lambda x, v=v, t=t: bit(v)(x) and bit(t)(x)))  # CZ
                for u, v, t in _it.combinations(range(n), 3):
                    L.append(zw(lambda x, u=u, v=v, t=t:
                                bit(u)(x) and bit(v)(x) and bit(t)(x)))        # CCZ
                for (u, v), t in _it.product(_it.combinations(range(n), 2), range(n)):
                    if t not in (u, v):
                        for eu in (0, 1):
                            for ev in (0, 1):
                                pred = (lambda x, u=u, v=v, eu=eu, ev=ev:
                                        bitv(u, eu)(x) and bitv(v, ev)(x))
                                L.append(xw(pred, t))             # CCX, 4 colours
                                L.append(izw(pred, t))            # CC(iZ)
    if 'schreier' in which:  # full Schreier set over reps e, i0, i0^2, i0^3
        reps = [[], [I(0)], [I(0)] * 2, [I(0)] * 3]
        deg = {}
        for name, g in gens.items(): deg[g] = 2 if name[0] == 'X' else 1
        for name, g in gens.items():
            for c in range(4):
                c2 = (c + deg[g]) % 4
                L.append(reps[c] + [g] + winv(reps[c2]))
    return L

# ---- HLT Todd-Coxeter with coincidence handling
def todd_coxeter(subgens, maxcosets=1200000):
    from array import array
    def col(g): return 2 * g if g >= 0 else 2 * (~g) + 1
    def icol(g): return 2 * (~g) if g < 0 else 2 * g + 1
    blank = array('i', [-1]) * (2 * NG)
    table = [array('i', blank)]
    parent = [0]
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    pending = []
    def merge(a, b):
        a, b = find(a), find(b)
        if a == b: return
        if a > b: a, b = b, a
        parent[b] = a
        pending.append(b)
    def define(c, g):
        table.append(array('i', blank))
        parent.append(len(parent))
        d = len(table) - 1
        table[c][col(g)] = d
        table[d][icol(g)] = c
        return d
    def scan(c, w):
        f = c; i = 0; n = len(w)
        while i < n:
            nxt = table[f][col(w[i])]
            if nxt < 0: break
            f = find(nxt); i += 1
        if i == n:
            if f != c: merge(f, c)
            return
        b = c; j = n
        while j > i + 1:
            prv = table[b][icol(w[j - 1])]
            if prv < 0: break
            b = find(prv); j -= 1
        # fill forward from f to position j-1, then close
        while i < j - 1:
            f = find(define(f, w[i])); i += 1
        # now i == j-1: close the gap with one deduction
        ex = table[f][col(w[i])]
        if ex < 0:
            table[f][col(w[i])] = b
            table[b][icol(w[i])] = f
        else:
            merge(find(ex), b)
    def process():
        while pending:
            b = pending.pop()
            a = find(b)
            for cc in range(2 * NG):
                d = table[b][cc]
                if d >= 0:
                    d = find(d)
                    e = table[a][cc]
                    if e < 0:
                        table[a][cc] = d
                        ic = cc + 1 if cc % 2 == 0 else cc - 1
                        ee = table[d][ic]
                        if ee < 0:
                            table[d][ic] = a
                        elif find(ee) != a:
                            merge(find(ee), a)
                    elif find(e) != d:
                        merge(find(e), d)
                table[b][cc] = -1
    for w in subgens:
        scan(0, w); process()
    rounds = 0
    while rounds < 200 and len(table) < maxcosets:
        rounds += 1
        changed = False
        before_live = sum(1 for c in range(len(table)) if find(c) == c)
        c = 0
        while c < len(table):
            if find(c) == c:
                for w in rels:
                    scan(find(c), w); process()
            c += 1
        for w in subgens:
            scan(find(0), w); process()
        live = [c for c in range(len(table)) if find(c) == c]
        full = all(table[c][cc] >= 0 for c in live for cc in range(2 * NG))
        if full and len(live) == before_live:
            return len(live), rounds, True
    live = [c for c in range(len(table)) if find(c) == c]
    return len(live), rounds, False

import time
for cand in (sys.argv[2:] or ['mm,mX,XX,KKb']):
    t0 = time.time()
    if cand.startswith('q:'):
        # quotient mode: letters as relators -> order of G/<<P'>>
        extra = letters(cand[2:].split(','))
        n0 = len(rels)
        rels.extend(extra)
        idx, r, ok = todd_coxeter([])
        del rels[n0:]
    else:
        idx, r, ok = todd_coxeter(letters(cand.split(',')))
    print(f"N={N}  P'={cand}: index {idx} {'(closed)' if ok else '(NOT closed)'}  "
          f"{r} rounds, {time.time() - t0:.1f}s", flush=True)
